<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { Activity, CircleAlert, Database, RefreshCw, Server, ShieldAlert } from 'lucide-vue-next'
import AdminLayout from '@/features/admin/components/AdminLayout.vue'
import AdminPanelState from '@/features/admin/components/AdminPanelState.vue'
import { useSession } from '@/app/stores/session'
import { useAdminSession } from '@/app/stores/admin-session'
import { fetchAdminRetention, fetchAdminSystemHealth, type AdminHealthPayload, type AdminHealthService, type AdminRetentionPayload } from '@/shared/api/admin'

const session = useSession(); const adminSession = useAdminSession(); const loading = ref(false); const error = ref<unknown>(null); const health = ref<AdminHealthPayload | null>(null); const retention = ref<AdminRetentionPayload | null>(null); const retentionLoading = ref(false); const retentionError = ref<unknown>(null)
const errorMessage = computed(() => error.value instanceof Error ? error.value.message : '系统健康读取失败')
const retentionErrorMessage = computed(() => retentionError.value instanceof Error ? retentionError.value.message : '数据保留策略读取失败')
function statusTone(status?: string) { return /healthy|up|ok|正常/i.test(status ?? '') ? 'ok' : /down|failed|error|异常/i.test(status ?? '') ? 'bad' : 'warn' }
async function load() { if (!session.token.value) { error.value = new Error('管理员会话已失效'); return }; loading.value = true; error.value = null; try { health.value = await fetchAdminSystemHealth(session.token.value) } catch (cause) { error.value = cause } finally { loading.value = false } }
async function loadRetention() { if (!session.token.value || !adminSession.can('admin.system.read')) return; retentionLoading.value = true; retentionError.value = null; try { retention.value = await fetchAdminRetention(session.token.value) } catch (cause) { retentionError.value = cause } finally { retentionLoading.value = false } }
onMounted(async () => { await adminSession.ensure(session.token.value); await Promise.all([load(), loadRetention()]) })
</script>
<template>
  <AdminLayout active-id="system"><section class="admin-page-v2"><header class="admin-page-v2__header"><div><div class="admin-page-v2__crumb">Admin / <strong>System</strong></div><h1>系统状态</h1><p>查看管理员范围内的服务健康、版本和错误摘要。</p></div><button class="admin-button-v2" type="button" :disabled="loading" @click="load"><RefreshCw :class="{ 'is-spinning': loading }" aria-hidden="true" />刷新</button></header><div v-if="error" class="admin-error-v2" role="alert"><ShieldAlert aria-hidden="true" /><span>{{ errorMessage }}</span><button type="button" @click="load">重试</button></div><div class="admin-grid"><article class="admin-card-v2 admin-span-8"><div class="admin-card-v2__header"><div><h2>服务健康</h2><p>不使用本地默认状态覆盖服务端结果。</p></div><Server aria-hidden="true" /></div><AdminPanelState v-if="loading" state="loading" title="正在检查系统状态" /><AdminPanelState v-else-if="error" state="error" :message="errorMessage" @retry="load" /><AdminPanelState v-else-if="!health" state="empty" title="尚未返回健康状态" message="服务端没有返回健康检查数据。" /><div v-else class="admin-table-wrap"><table class="admin-table-v2"><thead><tr><th>服务</th><th>状态</th><th>版本</th><th>检查时间</th><th>错误摘要</th></tr></thead><tbody><tr v-for="service in (health.services || []) as AdminHealthService[]" :key="service.serviceName"><td><strong>{{ service.serviceName || '未命名服务' }}</strong></td><td><span class="admin-status-v2" :class="`admin-status-v2--${statusTone(service.status)}`">{{ service.status || '未知' }}</span></td><td>{{ service.version || '-' }}</td><td>{{ service.checkedAt ? new Date(service.checkedAt).toLocaleString('zh-CN') : '-' }}</td><td>{{ service.errorSummary || '-' }}</td></tr></tbody></table><div v-if="!(health.services || []).length" class="admin-empty-v2"><Activity aria-hidden="true" /><div><strong>没有服务条目</strong><p>健康接口已返回，但没有可展示的服务记录。</p></div></div></div></article><article class="admin-card-v2 admin-span-4 admin-card-v2--pad"><h2>平台状态</h2><p>总体状态：<span class="admin-status-v2" :class="`admin-status-v2--${statusTone(health?.status)}`">{{ health?.status || '未读取' }}</span></p><p>版本：{{ health?.version || '-' }}</p><p>生成时间：{{ health?.generatedAt || '-' }}</p><p><CircleAlert aria-hidden="true" /> 保留策略写操作需要二次确认，当前页面只读。</p></article><article class="admin-card-v2 admin-span-12"><div class="admin-card-v2__header"><div><h2>数据保留策略</h2><p>读取审计、消息、工具结果和统计数据的服务端策略。</p></div><Database aria-hidden="true" /></div><AdminPanelState v-if="retentionLoading" state="loading" title="正在读取保留策略" /><AdminPanelState v-else-if="retentionError" state="error" :message="retentionErrorMessage" @retry="loadRetention" /><AdminPanelState v-else-if="!retention" state="empty" title="尚未返回保留策略" message="服务端没有提供当前策略，不使用本地默认天数。" /><div v-else class="admin-card-v2__body"><dl><dt>审计记录</dt><dd>{{ retention.auditDays ?? '-' }} 天</dd><dt>消息</dt><dd>{{ retention.messageDays ?? '-' }} 天</dd><dt>工具结果</dt><dd>{{ retention.toolResultDays ?? '-' }} 天</dd><dt>统计指标</dt><dd>{{ retention.metricsDays ?? '-' }} 天</dd><dt>版本</dt><dd>{{ retention.version ?? '-' }}</dd><dt>生效时间</dt><dd>{{ retention.effectiveAt || '-' }}</dd></dl><p>当前会话{{ adminSession.can('admin.system.retention.manage') ? '具备' : '不具备' }}保留策略变更权限；变更接口未在当前服务端路由中提供。</p></div></article></div></section></AdminLayout>
</template>
<style scoped>
dl { display:grid; grid-template-columns:120px 1fr; gap:16px; margin:0; }
dt { color:#a0a0a0; font-size:11px; }
dd { margin:0; font-size:12px; }
p svg { width:14px; vertical-align:-3px; }
</style>
